const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Villarrica volcano geometry (Chile)
  const villarrica = ee.Geometry.Point([-71.93, -39.42]).buffer(5000); // 5km radius

  // 2. Define time periods
  const targetStart = '2021-12-01';
  const targetEnd = '2022-02-01';
  const baselineYears = ee.List.sequence(2000, 2020);

  // 3. Load MODIS Snow Cover data
  const getSnowCollection = (startDate, endDate) => {
    return ee.ImageCollection('MODIS/006/MOD10A1')
      .filterDate(startDate, endDate)
      .filterBounds(villarrica)
      .select('NDSI_Snow_Cover');
  };

  // 4. Get target period data (Dec 2021 - Jan 2022)
  const targetCol = getSnowCollection(targetStart, targetEnd);
  const targetSize = targetCol.size().getInfo();

  console.log(`Target period images: ${targetSize}`);

  if (targetSize === 0) {
    console.log('No images for Dec 2021-Jan 2022.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate target period mean
  const targetMean = targetCol.mean();
  const targetStats = targetMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: villarrica,
    scale: 500,
    maxPixels: 1e9
  }).getInfo();

  const targetSnow = targetStats['NDSI_Snow_Cover_mean'];
  const targetCount = targetStats['NDSI_Snow_Cover_count'];

  console.log(`Target valid pixels: ${targetCount}`);

  if (targetCount === 0) {
    console.log('No valid pixels in target period.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Calculate baseline (2000-2020) Dec-Jan averages
  const baselineImages = baselineYears.map((year) => {
    const y = ee.Number(year);
    const start = ee.Date.fromYMD(y, 12, 1);
    const end = ee.Date.fromYMD(y.add(1), 2, 1);
    const col = getSnowCollection(start, end);
    return col.mean().set('year', year);
  });

  const baselineCol = ee.ImageCollection.fromImages(baselineImages);
  const baselineSize = baselineCol.size().getInfo();

  console.log(`Baseline period images: ${baselineSize}`);

  if (baselineSize === 0) {
    console.log('No baseline data.');
    console.log('<answer>C1</answer>');
    return;
  }

  const baselineMean = baselineCol.mean();
  const baselineStats = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: villarrica,
    scale: 500,
    maxPixels: 1e9
  }).getInfo();

  const baselineSnow = baselineStats['NDSI_Snow_Cover_mean'];
  const baselineCount = baselineStats['NDSI_Snow_Cover_count'];

  console.log(`Baseline valid pixels: ${baselineCount}`);

  if (baselineCount === 0) {
    console.log('No valid pixels in baseline.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Validate calculations
  if (targetSnow === null || targetSnow === undefined || isNaN(targetSnow) ||
      baselineSnow === null || baselineSnow === undefined || isNaN(baselineSnow)) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare and output results
  console.log(`Dec 2021-Jan 2022 mean snow: ${targetSnow.toFixed(2)}%`);
  console.log(`2000-2020 Dec-Jan mean snow: ${baselineSnow.toFixed(2)}%`);
  console.log(`Difference: ${(targetSnow - baselineSnow).toFixed(2)}%`);

  if (targetSnow > baselineSnow) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
